head.script:
scwin.trigger1_onclick = function() {
    var opts = {
        "id": "popup_litewindow",
        "type": "litewindow",
        "width": 300 + "px",
        "height": 300 + "px",
        "top": 50,
        "left": 50,
        "popupName": "close button test",
        "modal": false,
        "useIFrame": true,
        "title": "focusTest",
        "disableCloseButton": true
    };
    WebSquare.util.openPopup("openPopup_CloseButton_SKT-680_(WSQ-2160)_sub.xml", opts);
};
scwin.trigger2_onclick = function() {
    WebSquare.util.getPopup("popup_litewindow").setCloseButtonStatus(true);
};
scwin.trigger3_onclick = function() {
    WebSquare.util.getPopup("popup_litewindow").setCloseButtonStatus(false);
};
scwin.checktype = function() {
    return typeof popup_litewindow;
}
scwin.checkVal = function() {
    return window.getComputedStyle((document.getElementById('popup_litewindow_close') || document.getElementById('mf_popup_litewindow_close'))).getPropertyValue('cursor') == 'pointer';
}
scwin.checkVal1 = function() {
    return window.getComputedStyle((document.getElementById('popup_litewindow_close') || document.getElementById('mf_popup_litewindow_close'))).getPropertyValue('cursor') == 'default';
}
scwin.checkVal2 = function() {
    return window.getComputedStyle((document.getElementById('popup_litewindow_close') || document.getElementById('mf_popup_litewindow_close'))).getPropertyValue('cursor') == 'pointer';
}
scwin.checkVal3 = function() {
    return window.getComputedStyle((document.getElementById('popup_litewindow_close') || document.getElementById('mf_popup_litewindow_close'))).getPropertyValue('cursor') == 'default'
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    requires("uiplugin.popup");
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 27-Feb-2018
    //End unitTest
}
